const crypto = require('crypto');

const runId = $('Store Run ID').first().json.run_id;
const items = $input.all();

const clean = (v) => {
  const value = String(v ?? '').trim();
  if (!value || value === 'N/A' || value === 'N, /, A') return '';
  return value;
};

const cleanForKey = (v) =>
  clean(v).toLowerCase().replace(/[^a-z0-9]/g, '') || 'unknown';

const hashMd5 = (text) =>
  crypto.createHash('md5').update(String(text ?? '')).digest('hex');

const toArray = (v) => {
  if (Array.isArray(v)) return v;
  if (!v || v === 'N/A') return [];
  return [v];
};

const stripHtml = (html) =>
  clean(html)
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const parseSeekSalary = (salaryText) => {
  const text = clean(salaryText);

  if (!text) {
    return {
      min: null,
      max: null,
      currency: 'AUD',
      period: null,
      salaryText: null,
    };
  }

  const lower = text.toLowerCase();

  let period = null;
  if (lower.includes('hour') || lower.includes('p.h')) period = 'hourly';
  else if (lower.includes('week')) period = 'weekly';
  else if (lower.includes('month')) period = 'monthly';
  else if (
    lower.includes('year') ||
    lower.includes('annum') ||
    lower.includes('p.a') ||
    lower.includes('ote')
  ) period = 'annual';

  const numbers = text.replace(/,/g, '').match(/\d+(\.\d+)?\s*k?/gi);

  if (!numbers || numbers.length === 0) {
    return {
      min: null,
      max: null,
      currency: 'AUD',
      period,
      salaryText: text,
    };
  }

  const parsed = numbers.map(n => {
    const raw = n.toLowerCase().replace(/\s/g, '');
    let value = parseFloat(raw.replace('k', ''));

    if (raw.includes('k')) value = value * 1000;

    return value;
  });

  return {
    min: parsed[0] ?? null,
    max: parsed[1] ?? parsed[0] ?? null,
    currency: 'AUD',
    period,
    salaryText: text,
  };
};

const buildEmbeddingText = (fields) => [
  fields.title ? `Title: ${fields.title}` : null,
  fields.classification ? `Classification: ${fields.classification}` : null,
  fields.sub_classification ? `Sub Classification: ${fields.sub_classification}` : null,
  fields.employment_type ? `Employment Type: ${fields.employment_type}` : null,
  fields.work_arrangement ? `Work Arrangement: ${fields.work_arrangement}` : null,
  fields.location ? `Location: ${fields.location}` : null,
  fields.highlights ? `Highlights:\n${fields.highlights}` : null,
  fields.description ? `Description:\n${fields.description.substring(0, 4000)}` : null,
].filter(Boolean).join('\n\n').slice(0, 8000);

return items.map(item => {
  const job = item.json;

  const source = 'seek';
  const sourceJobId = String(job.id || '');

  const title = clean(job.title);
  const company = clean(job.advertiser?.name || job.companyName);

  const location = clean(
    job.joblocationInfo?.displayLocation ||
    job.jobLocation?.[0]?.label
  );

  const city = clean(
    job.joblocationInfo?.suburb ||
    job.joblocationInfo?.location ||
    job.jobLocation?.[0]?.label
  );

  const country = clean(
    job.joblocationInfo?.countryCode ||
    job.jobLocation?.[0]?.countryCode
  ) || 'AU';

  const stateMatch = location.match(/\b(NSW|VIC|QLD|SA|WA|TAS|NT|ACT)\b/i);
  const state = stateMatch ? stateMatch[1].toUpperCase() : '';

  const classification = clean(
    job.classificationInfo?.classification ||
    job.classification
  ) || null;

  const subClassification = clean(
    job.classificationInfo?.subClassification ||
    job.subClassification
  ) || null;

  const employmentType = clean(job.workTypes || job.workType) || null;

  const workArrangement = clean(job.workArrangements) || null;

  const descriptionSections = toArray(job.content?.sections)
    .map(clean)
    .filter(Boolean);

  const description =
    descriptionSections.length > 0
      ? descriptionSections.join('\n')
      : clean(job.teaser || job.content?.jobHook || stripHtml(job.content?.unEditedContent));

  const highlightsArr = toArray(job.content?.bulletPoints || job.bulletPoints)
    .map(clean)
    .filter(Boolean);

  const highlights = highlightsArr.length
    ? '• ' + highlightsArr.join('\n• ')
    : null;

  const tags = toArray(job.tags || job.companyTags)
    .map(clean)
    .filter(Boolean)
    .join(', ') || null;

  const salaryParsed = parseSeekSalary(job.salary);

  const listingUrl = clean(job.jobLink);
  const applyUrl = clean(job.applyLink);

  const postedAt = job.listedAt || job.listingDate || null;
  const expiresAt = job.expiresAtUtc || null;

  const dedupeKey = hashMd5([
    cleanForKey(title),
    cleanForKey(company),
    cleanForKey(location),
  ].join('|'));

  const embeddingText = buildEmbeddingText({
    title,
    location,
    employment_type: employmentType,
    work_arrangement: workArrangement,
    classification,
    sub_classification: subClassification,
    highlights,
    description,
  });

  const embeddingHash = hashMd5(embeddingText);

  return {
    json: {
      // RPC parameters
      p_source: source,
      p_source_job_id: sourceJobId,
      p_title: title,
      p_company: company,
      p_location: location,
      p_state: state,
      p_country: country,
      p_description: description,
      p_classification: classification,
      p_sub_classification: subClassification,
      p_listing_url: listingUrl,
      p_apply_url: applyUrl,
      p_salary_min: salaryParsed.min,
      p_salary_max: salaryParsed.max,
      p_salary_currency: salaryParsed.currency,
      p_salary_period: salaryParsed.period,
      p_work_arrangement: workArrangement,
      p_employment_type: employmentType,
      p_posted_at: postedAt,
      p_expires_at: expiresAt,
      p_raw_payload: job,
      p_dedupe_key: dedupeKey,
      p_embedding_text: embeddingText,
      p_embedding_hash: embeddingHash,
      p_ingestion_run_id: runId

      // Optional direct job-table-style fields for debugging/inspection
      // source,
      // source_job_id: sourceJobId,
      // title,
      // company,
      // location,
      // city,
      // state,
      // country,
      // salary: salaryParsed.salaryText,
      // salary_min: salaryParsed.min,
      // salary_max: salaryParsed.max,
      // salary_currency: salaryParsed.currency,
      // salary_period: salaryParsed.period,
      // job_url: listingUrl,
      // apply_url: applyUrl,
      // description,
      // classification,
      // sub_classification: subClassification,
      // work_arrangement: workArrangement,
      // employment_type: employmentType,
      // posted_at: postedAt,
      // expires_at: expiresAt,
      // dedupe_key: dedupeKey,
      // embedding_text: embeddingText,
      // embedding_hash: embeddingHash,
      // embedding_status: 'pending',
      // raw_payload: job
    }
  };
});

const crypto = require('crypto');

const runId = $('Store Run ID').first().json.run_id;

const clean = (v) => {
  const value = String(v ?? '').trim();
  if (!value || value === 'N/A' || value === 'N, /, A') return '';
  return value;
};

const cleanForKey = (v) =>
  clean(v).toLowerCase().replace(/[^a-z0-9]/g, '') || 'unknown';

const hashMd5 = (text) =>
  crypto.createHash('md5').update(String(text ?? '')).digest('hex');

const toArray = (v) => {
  if (Array.isArray(v)) return v;
  if (!v || v === 'N/A') return [];
  return [v];
};

const getLocation = (job) =>
  clean(
    job.location?.formattedAddressShort ||
    job.location?.formattedAddressLong ||
    job.location?.fullAddress ||
    [job.location?.city, job.location?.countryCode].filter(Boolean).join(' ')
  );

const getCity = (job) =>
  clean(job.location?.city);

const getState = (location) => {
  const match = String(location).match(/\b(NSW|VIC|QLD|SA|WA|TAS|NT|ACT)\b/i);
  return match ? match[1].toUpperCase() : '';
};

const getWorkArrangement = (job) => {
  const attrs = toArray(job.attributes).map(a => String(a).toLowerCase());

  if (job.isRemote) return 'Remote';
  if (attrs.includes('hybrid work') || attrs.includes('hybrid')) return 'Hybrid';
  if (attrs.includes('work from home')) return 'Hybrid';
  if (attrs.includes('in-person')) return 'In-person';

  return 'In-person';
};

const normaliseSalaryPeriod = (value) => {
  const text = String(value || '').toLowerCase();

  if (text.includes('hour') || text.includes('hourly')) return 'hourly';
  if (text.includes('week') || text.includes('weekly')) return 'weekly';
  if (text.includes('month') || text.includes('monthly')) return 'monthly';
  if (
    text.includes('year') ||
    text.includes('yearly') ||
    text.includes('annual') ||
    text.includes('annum') ||
    text.includes('p.a')
  ) return 'annual';

  return null;
};

const getSalary = (job) => {
  const salary = job.salary || {};
  const salaryText = clean(salary.salaryText);

  let min = salary.salaryMin != null ? Number(salary.salaryMin) : null;
  let max = salary.salaryMax != null ? Number(salary.salaryMax) : null;

  const currency = clean(salary.salaryCurrency) || 'AUD';
  const period = normaliseSalaryPeriod(salary.salaryType || salaryText);

  if ((min == null && max == null) && salaryText) {
    const numbers = salaryText
      .replace(/,/g, '')
      .match(/\d+(\.\d+)?\s*k?/gi);

    if (numbers && numbers.length > 0) {
      const parsed = numbers.map(n => {
        const raw = n.toLowerCase().replace(/\s/g, '');
        let value = parseFloat(raw.replace('k', ''));

        if (raw.includes('k')) value = value * 1000;

        return value;
      });

      if (/up to/i.test(salaryText)) {
        min = null;
        max = parsed[0];
      } else if (/from/i.test(salaryText)) {
        min = parsed[0];
        max = null;
      } else {
        min = parsed[0] ?? null;
        max = parsed[1] ?? parsed[0] ?? null;
      }
    }
  }

  return {
    min,
    max,
    currency,
    period,
    salaryText: salaryText || null,
  };
};

const buildEmbeddingText = (fields) => [
  fields.title ? `Title: ${fields.title}` : null,
  fields.classification ? `Classification: ${fields.classification}` : null,
  fields.sub_classification ? `Sub Classification: ${fields.sub_classification}` : null,
  fields.employment_type ? `Employment Type: ${fields.employment_type}` : null,
  fields.work_arrangement ? `Work Arrangement: ${fields.work_arrangement}` : null,
  fields.location ? `Location: ${fields.location}` : null,
  fields.highlights ? `Highlights:\n${fields.highlights}` : null,
  fields.tags ? `Tags: ${fields.tags}` : null,
  fields.description ? `Description:\n${fields.description.substring(0, 4000)}` : null,
].filter(Boolean).join('\n\n').slice(0, 8000);

const jobs = [];

for (const item of $input.all()) {
  const wrapper = item.json || {};

  if (Array.isArray(wrapper.returnvalue?.data)) {
    jobs.push(...wrapper.returnvalue.data);
  }
}

return jobs.map(job => {
  const source = 'indeed';
  const sourceJobId = String(job.jobKey || '');

  const title = clean(job.title);
  const company = clean(job.companyName);
  const location = getLocation(job);
  const city = getCity(job);
  const state = getState(location);
  const country = clean(job.location?.countryCode) || 'AU';

  const jobTypes = toArray(job.jobType).map(clean).filter(Boolean);
  const employmentType = jobTypes.join(', ') || null;

  const occupation = toArray(job.occupation).map(clean).filter(Boolean);
  const classification = occupation[0] || null;
  const subClassification = occupation.length > 1
    ? occupation.slice(1).join(' > ')
    : null;

  const workArrangement = getWorkArrangement(job);

  const description = clean(job.descriptionText);

  const benefits = toArray(job.benefits).map(clean).filter(Boolean);
  const attributes = toArray(job.attributes).map(clean).filter(Boolean);
  const requirements = toArray(job.requirements)
    .map(r => clean(r.label))
    .filter(Boolean);

  const highlightsArr = [...new Set([
    ...benefits,
    ...requirements,
  ])];

  const highlights = highlightsArr.length
    ? '• ' + highlightsArr.join('\n• ')
    : null;

  const tags = [...new Set([
    ...attributes,
    ...requirements,
  ])].join(', ') || null;

  const salaryParsed = getSalary(job);

  const listingUrl = clean(job.jobUrl);
  const applyUrl = clean(job.applyUrl);

  const postedAt = job.datePublished || null;
  const expiresAt = job.expired === true ? new Date().toISOString() : null;

  const dedupeKey = hashMd5([
    cleanForKey(title),
    cleanForKey(company),
    cleanForKey(location),
  ].join('|'));

  const embeddingText = buildEmbeddingText({
    title,
    location,
    employment_type: employmentType,
    work_arrangement: workArrangement,
    classification,
    sub_classification: subClassification,
    tags,
    highlights,
    description,
  });

  const embeddingHash = hashMd5(embeddingText);

  return {
    json: {
      p_source: source,
      p_source_job_id: sourceJobId,
      p_title: title,
      p_company: company,
      p_location: location,
      p_state: state,
      p_country: country,
      p_description: description,
      p_classification: classification,
      p_sub_classification: subClassification,
      p_listing_url: listingUrl,
      p_apply_url: applyUrl,
      p_salary_min: salaryParsed.min,
      p_salary_max: salaryParsed.max,
      p_salary_currency: salaryParsed.currency,
      p_salary_period: salaryParsed.period,
      p_work_arrangement: workArrangement,
      p_employment_type: employmentType,
      p_posted_at: postedAt,
      p_expires_at: expiresAt,
      p_raw_payload: job,
      p_dedupe_key: dedupeKey,
      p_embedding_text: embeddingText,
      p_embedding_hash: embeddingHash,
      p_ingestion_run_id: runId

      // source,
      // source_job_id: sourceJobId,
      // title,
      // company,
      // location,
      // city,
      // state,
      // country,
      // salary: salaryParsed.salaryText,
      // salary_min: salaryParsed.min,
      // salary_max: salaryParsed.max,
      // salary_currency: salaryParsed.currency,
      // salary_period: salaryParsed.period,
      // job_url: listingUrl,
      // apply_url: applyUrl,
      // description,
      // classification,
      // sub_classification: subClassification,
      // work_arrangement: workArrangement,
      // employment_type: employmentType,
      // posted_at: postedAt,
      // expires_at: expiresAt,
      // dedupe_key: dedupeKey,
      // embedding_text: embeddingText,
      // embedding_hash: embeddingHash,
      // embedding_status: 'pending',
      // raw_payload: job
    }
  };
});

const RULES = [
  { field: 'p_title',         minLen: 3,  code: 'missing_title' },
  { field: 'p_company',       minLen: 2,  code: 'missing_company' },
  { field: 'p_location',      minLen: 1,  code: 'missing_location' },
  { field: 'p_source_job_id', minLen: 1,  code: 'missing_source_job_id' },
  { field: 'p_description',   minLen: 50, code: 'missing_description' },
];
return $input.all().map(item => {
  const job = item.json;
  let valid = true, rejectionCode = null, rejectionReason = null;
  for (const rule of RULES) {
    const val = String(job[rule.field] || '').trim();
    if (val.length < rule.minLen) {
      valid = false;
      rejectionCode = rule.code;
      rejectionReason = "Field '" + rule.field + "' too short (got " + val.length + ", min " + rule.minLen + ")";
      break;
    }
  }
  return { json: { ...job,
    _valid: valid ? 'yes' : 'no',
    _rejection_code: valid ? null : rejectionCode,
    _rejection_reason: valid ? null : rejectionReason,
    _rejected_at: valid ? null : new Date().toISOString()
  }};
});

